#!/usr/bin/env python3
"""Generate core/.../FoodData.kt from tools/usda_foods.json.

usda_foods.json holds per-100 g values copied from USDA FoodData Central, SR Legacy (April 2018 CSV
download, fdc.nal.usda.gov), keyed by a short id, with each food's FDC id and USDA description.
"""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
foods = json.loads((ROOT / "tools/usda_foods.json").read_text())
out = [
    "// GENERATED by tools/gen_foods.py from tools/usda_foods.json (USDA FoodData Central, SR Legacy). Do not edit.",
    "package com.feidbo.marathon.core",
    "",
    "/** Per 100 g, from USDA FoodData Central. */",
    "internal val usdaFoods: Map<String, Food> = mapOf(",
]
for key in sorted(foods):
    f = foods[key]
    desc = f["desc"].replace('"', '\\"')
    out.append(f'    "{key}" to Food("{key}", {f["fdc"]}, "{desc}", {f["kcal"]}, {f["p"]}, {f["c"]}, {f["f"]}),')
out.append(")")
(ROOT / "core/src/main/kotlin/com/feidbo/marathon/core/FoodData.kt").write_text("\n".join(out) + "\n", encoding="utf-8")
